WHERE sale_targets.is_active = 1
AND ( sale_targets.target_name LIKE CONCAT("%", #{filter.searchText}, "%") OR sale_targets.sale_target_code LIKE CONCAT("%", #{filter.searchText}, "%") OR sale_targets.id IN ( SELECT sale_target_customer_markets.sale_target_id FROM sale_target_customer_markets INNER JOIN customer_markets ON customer_markets.id = sale_target_customer_markets.market_id WHERE sale_target_customer_markets.is_active = 1 AND customer_markets.is_active = 1 AND customer_markets.name LIKE CONCAT("%", #{filter.searchText}, "%") ) )
AND sale_targets.created_by = #{userId}

